WITH with_last AS (SELECT s.*, latest.inventory_last_restock, latest.quantity FROM stores s JOIN LATERAL (SELECT c.last_restock AS inventory_last_restock, c.quantity FROM inventory c WHERE c.store_id = s.id ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) latest ON TRUE), ranked AS (SELECT * FROM with_last QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date NULLS LAST, id) = 1), scored AS (SELECT id, sqft, quantity, PERCENT_RANK() OVER (PARTITION BY region ORDER BY quantity DESC) AS quantity_percent_rank, ROW_NUMBER() OVER (PARTITION BY region, city ORDER BY sqft, id) AS row_seq FROM ranked), enriched AS (SELECT *, MAX(quantity_percent_rank) OVER (ORDER BY quantity_percent_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_quantity_percent_rank, COUNT(quantity_percent_rank) OVER (ORDER BY quantity_percent_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_quantity_percent_rank, MIN(quantity_percent_rank) OVER (ORDER BY quantity_percent_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_quantity_percent_rank, PERCENT_RANK() OVER (ORDER BY quantity_percent_rank DESC) AS quantity_percent_rank_percent_rank FROM scored), eligible AS (SELECT s.* FROM enriched s WHERE EXISTS (SELECT 1 FROM store_sales x WHERE x.store_id = s.id AND x.store_id IN (1, 2, 4))), with_windows AS (SELECT *, LEAD(quantity_percent_rank) OVER w_recent AS next_quantity_percent_rank, LAG(quantity_percent_rank) OVER w_recent AS prev_quantity_percent_rank, LAG(running_max_quantity_percent_rank) OVER w_recent AS prev_running_max_quantity_percent_rank, ROW_NUMBER() OVER w_recent AS row_seq_2 FROM eligible WINDOW w_recent AS (ORDER BY running_max_quantity_percent_rank, id)) SELECT id, sqft, quantity_percent_rank, running_max_quantity_percent_rank, running_count_quantity_percent_rank, running_min_quantity_percent_rank, quantity_percent_rank_percent_rank, next_quantity_percent_rank, prev_quantity_percent_rank, LAG(row_seq) OVER w_part AS prev_row_seq, LEAD(row_seq) OVER w_part AS next_row_seq, LEAD(quantity_percent_rank) OVER w_part AS next_quantity_percent_rank_2, LAG(quantity_percent_rank) OVER w_part AS prev_quantity_percent_rank_2, ROW_NUMBER() OVER w_part AS event_seq, NTILE(4) OVER (ORDER BY running_min_quantity_percent_rank, id) AS running_min_quantity_percent_rank_bucket FROM with_windows WINDOW w_part AS (ORDER BY row_seq, id)
